INSERT INTO public.tools_catalog (id, name, description, category, tool_types, source, is_live, is_premium, is_free, dedicated_route, display_order, extra_categories)
VALUES
  ('catalogue-photo-studio', 'Catalogue Photo Studio', 'Turn one phone photo of a product into marketplace-ready shots: white background, angles, close-up, scale and infographic base.', 'AI Image Generation', ARRAY['Product Photography', 'Image Editing'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling']),
  ('lifestyle-scene-generator', 'Lifestyle Scene Generator', 'Place your product in real-life Indian scenes: modern kitchen, festive living room, office desk, outdoor café and more.', 'AI Image Generation', ARRAY['Product Photography', 'AI Image'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling', 'Content Creation']),
  ('virtual-model-try-on', 'Virtual Model Try-On', 'Show your garment, saree or kurta on an AI model of the body type and setting you choose, from a flat or hanger photo.', 'AI Image Generation', ARRAY['Fashion', 'AI Image'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling']),
  ('jewellery-shot-studio', 'Jewellery Shot Studio', 'Make luxury jewellery photos from a phone shot: velvet and marble sets, on-model neck and hand shots, and sparkle close-ups.', 'AI Image Generation', ARRAY['Jewellery', 'Product Photography'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling']),
  ('food-menu-photo-studio', 'Food Menu Photo Studio', 'Turn quick kitchen photos into appetising menu shots for Zomato, Swiggy and your menu card: top-down, plated, thali and close-ups.', 'AI Image Generation', ARRAY['Food', 'Product Photography'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling', 'Marketing & Sales']),
  ('marketplace-listing-writer', 'Marketplace Listing Writer', 'Snap your product and get a full Amazon, Flipkart or Meesho listing: title, bullets, description, keywords and attributes.', 'Online Selling', ARRAY['Copywriting', 'E-commerce'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('a-plus-content-builder', 'A+ Content Builder', 'Plan rich A+ content for Amazon or Flipkart: module layout, headlines, comparison chart and image briefs, with optional banners.', 'Online Selling', ARRAY['E-commerce', 'Design'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('packaging-design-studio', 'Packaging Design Studio', 'See your product in new packaging designs: box, pouch, jar label and gift pack mock-ups in styles that suit your brand.', 'AI Image Generation', ARRAY['Packaging', 'Design'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling']),
  ('property-photo-enhancer', 'Property Photo Enhancer', 'Make property listing photos bright and inviting: fix light and colour, straighten lines, declutter and virtually stage empty rooms.', 'AI Image Generation', ARRAY['Real Estate', 'Image Editing'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling', 'Photo Enhance & Retouch']),
  ('car-listing-studio', 'Car Listing Studio', 'Turn used car or bike photos into clean listing images: studio backdrop, showroom look and tidy interiors, without hiding any damage.', 'AI Image Generation', ARRAY['Automobile', 'Product Photography'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling']),
  ('product-video-ad-maker', 'Product Video Ad Maker', 'Get 5 short video ad scripts with hooks, shot lists, on-screen text, voice-over and editing notes for Reels, Shorts and ads.', 'Online Selling', ARRAY['Video', 'Advertising'], 'featured', true, false, false, NULL, 0, ARRAY['Content Creation', 'Marketing & Sales']),
  ('online-store-launch-kit', 'Online Store Launch Kit', 'Launch your own online store: platform choice, setup checklist, pages, policies, payments, shipping and the first 30 days of marketing.', 'Online Selling', ARRAY['E-commerce', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('seller-account-health-analyser', 'Seller Account Health Analyser', 'Upload marketplace reports or screenshots to find why sales, ratings or account health dropped, with a fix plan for each issue.', 'Online Selling', ARRAY['E-commerce', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('product-idea-validator', 'Product Idea Validator', 'Test a product idea before you invest: demand signals, competition, landed cost, margin, pricing and a cheap 2-week test plan.', 'Online Selling', ARRAY['Research', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('return-reduction-analyser', 'Return Reduction Analyser', 'Upload return reasons and reviews to find why customers send products back, with listing, size, packing and quality fixes.', 'Online Selling', ARRAY['E-commerce', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('size-chart-and-fit-guide-builder', 'Size Chart and Fit Guide Builder', 'Build clear size charts and fit guides from your measurements: body vs garment sizes, how to measure, fit notes and FAQs.', 'Online Selling', ARRAY['Fashion', 'E-commerce'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('artisan-story-kit', 'Artisan Story Kit', 'Tell an artisan''s craft story by voice and get product stories, tags, a brand page, social posts and exhibition text.', 'Online Selling', ARRAY['Storytelling', 'E-commerce'], 'featured', true, false, false, NULL, 0, ARRAY['Personal']),
  ('merchandise-mockup-studio', 'Merchandise Mockup Studio', 'Put your logo or artwork on T-shirts, mugs, tote bags, caps and notebooks as realistic mock-ups for selling or gifting.', 'AI Image Generation', ARRAY['Merchandise', 'Design'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling']),
  ('whatsapp-catalogue-maker', 'WhatsApp Catalogue Maker', 'Turn your product list into a WhatsApp catalogue: collections, product titles, descriptions, prices, order messages and broadcasts.', 'Online Selling', ARRAY['WhatsApp', 'E-commerce'], 'featured', true, false, false, NULL, 0, ARRAY['Marketing & Sales']),
  ('d2c-brand-launch-planner', 'D2C Brand Launch Planner', 'A full plan to launch a direct-to-consumer brand: positioning, product range, pricing, channels, budget, team and first-year roadmap.', 'Online Selling', ARRAY['Planning', 'Branding'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy'])
